	private static final int WORLDMAP_BACKING = InterfaceID.Orbs.WORLDMAP_BACKING;
	private static final int WORLDMAP_TOOLTIP = InterfaceID.Orbs.TOOLTIP;

	// Base game wiki orb
	private static final int WIKI_ICON = InterfaceID.Orbs.WIKI_ICON;

	// Wiki orb parent container.
	// Used to target the orb created by Wiki plugin, a dynamic replacement child.
	private static final int WIKI_CONTAINER = InterfaceID.Orbs.WIKI;

	// Compass/logout widgets.
	private static final int MODERN_COMPASS_CLICK = InterfaceID.ToplevelPreEoc.COMPASSCLICK;
	private static final int CLASSIC_COMPASS_CLICK = InterfaceID.ToplevelOsrsStretch.COMPASSCLICK;
	private static final int FIXED_COMPASS_CLICK = InterfaceID.Toplevel.COMPASSCLICK;

	private static final int LOGOUT_STONE = InterfaceID.ToplevelPreEoc.STONE10;
	// The icon is a sibling of the backing/button, not a child of it.
	private static final int LOGOUT_ICON = InterfaceID.ToplevelPreEoc.ICON10;

	// Radar noclick regions that cover the world map/wiki/logout/radar orb areas.
	// Resizable Modern
	private static final int MODERN_MAP_NOCLICK_0 = InterfaceID.ToplevelPreEoc.MAP_NOCLICK_0; // Radar/logout
	private static final int MODERN_MAP_NOCLICK_1 = InterfaceID.ToplevelPreEoc.MAP_NOCLICK_1;
	private static final int MODERN_MAP_NOCLICK_2 = InterfaceID.ToplevelPreEoc.MAP_NOCLICK_2;
	private static final int MODERN_MAP_NOCLICK_3 = InterfaceID.ToplevelPreEoc.MAP_NOCLICK_3;
	private static final int MODERN_MAP_NOCLICK_4 = InterfaceID.ToplevelPreEoc.MAP_NOCLICK_4;
	private static final int MODERN_MAP_NOCLICK_5 = InterfaceID.ToplevelPreEoc.MAP_NOCLICK_5;

	// Resizable Classic
	private static final int CLASSIC_MAP_NOCLICK_0 = InterfaceID.ToplevelOsrsStretch.MAP_NOCLICK_0; // Radar/logout
	private static final int CLASSIC_MAP_NOCLICK_1 = InterfaceID.ToplevelOsrsStretch.MAP_NOCLICK_1;
	private static final int CLASSIC_MAP_NOCLICK_2 = InterfaceID.ToplevelOsrsStretch.MAP_NOCLICK_2;
	private static final int CLASSIC_MAP_NOCLICK_3 = InterfaceID.ToplevelOsrsStretch.MAP_NOCLICK_3;
	private static final int CLASSIC_MAP_NOCLICK_4 = InterfaceID.ToplevelOsrsStretch.MAP_NOCLICK_4;
	private static final int CLASSIC_MAP_NOCLICK_5 = InterfaceID.ToplevelOsrsStretch.MAP_NOCLICK_5;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private KeyManager keyManager;

	@Inject
	private OrbClickthroughConfig config;

	@Inject
	private OrbWidgetTransformer widgetTransformer;

	@Inject
	private OrbOverlayCompatibility overlayCompatibility;

	private HotkeyListener hotkeyListener;
	private boolean running;

	@Inject
	private CompassAppearance compassAppearance;

	private boolean hotkeyHeld;
	private boolean toggleActive;

	private boolean noClickRegionsSynced;
	private int noClickRegionsSyncedForMapNoClick0 = NO_ACTIVE_MAP_NOCLICK_0;
	private boolean orbWidgetsApplied;

	@Override
	protected void startUp()
	{
		running = true;
		log.debug("Orb Clickthrough started");

		hotkeyListener = new HotkeyListener(() -> config.hotkey())
		{
			@Override
			public void hotkeyPressed()
			{
				if (config.activationMode() == OrbClickthroughActivationMode.TOGGLE_CLICK_THROUGH)
				{
					toggleActive = !toggleActive;
				}
				else
				{
					hotkeyHeld = true;
				}

				clientThread.invokeLater(OrbClickthroughPlugin.this::syncState);
			}

			@Override
			public void hotkeyReleased()
			{
				if (config.activationMode() != OrbClickthroughActivationMode.TOGGLE_CLICK_THROUGH)
				{
					hotkeyHeld = false;
					clientThread.invokeLater(OrbClickthroughPlugin.this::syncState);
				}
			}
		};

		keyManager.registerKeyListener(hotkeyListener);
		markNoClickRegionsDirty();
		clientThread.invokeLater(this::syncState);
	}

	@Override
	protected void shutDown()
	{
		running = false;
		if (hotkeyListener != null)
		{
			keyManager.unregisterKeyListener(hotkeyListener);
			hotkeyListener = null;
		}

		clientThread.invokeLater(() ->
		{
			compassAppearance.stop();
			overlayCompatibility.stop();
			widgetTransformer.restoreEverythingChangedByUs();
			hotkeyHeld = false;
			toggleActive = false;
			orbWidgetsApplied = false;
			markNoClickRegionsDirty();
		});

		log.debug("Orb Clickthrough stopped");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			widgetTransformer.restoreEverythingChangedByUs();
			hotkeyHeld = false;
			toggleActive = false;
			orbWidgetsApplied = false;
			markNoClickRegionsDirty();
			return;
		}

		markNoClickRegionsDirty();
		clientThread.invokeLater(this::syncState);
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		/*
		 * Widgets can be recreated after login, layout changes, or other plugin changes.
		 * Resync on widget loads instead of doing the same work every client tick.
		 */
		markNoClickRegionsDirty();

		if (orbWidgetsApplied)
		{
			widgetTransformer.restoreOrbWidgetsChangedByUs();
			orbWidgetsApplied = false;
		}

		clientThread.invokeLater(this::syncState);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CONFIG_GROUP.equals(event.getGroup()))
		{
			return;
		}

		clientThread.invokeLater(() ->
		{
			widgetTransformer.restoreEverythingChangedByUs();
			if ("hotkey".equals(event.getKey()) || "activationMode".equals(event.getKey()))
			{
				hotkeyHeld = false;
				toggleActive = false;
			}
			orbWidgetsApplied = false;
			markNoClickRegionsDirty();
			syncState();
		});
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		// Remove the previous frame's tint before game scripts update orb visuals.
		widgetTransformer.restoreTransparency();
		widgetTransformer.restoreHoverEffects();
		// This is deliberately cheap and idempotent. It also repairs widget state
		// if another plugin or a client update recreates or resets an orb child.
		syncState();
		syncExtraNoClickRegionState();
	}

	@Subscribe(priority = -100)
	public void onBeforeRender(BeforeRender event)
	{
		if (running)
		{
			overlayCompatibility.sync();
			compassAppearance.beginFrame();
		}
		if (client.getGameState() == GameState.LOGGED_IN && shouldApplyNow())
		{
			if (config.suppressOrbTooltips())
			{
				widgetTransformer.suppressHoverEffects();
			}
			widgetTransformer.applyTransparency(config.clickThroughTransparency());
		}
	}

	boolean suppressPluginTooltip(String orb)
	{
		return running && client.getGameState() == GameState.LOGGED_IN && shouldApplyNow()
				&& managesOrb(orb) && config.suppressOrbTooltips();
	}

	float pluginOverlayOpacity(String orb)
	{
		return running && client.getGameState() == GameState.LOGGED_IN && shouldApplyNow()
				&& managesOrb(orb) && config.fadePluginOverlays()
				? 1f - Math.max(0, Math.min(100, config.clickThroughTransparency())) / 100f : 1f;
	}

	float nativeOrbOpacity(String orb)
	{
		return running && client.getGameState() == GameState.LOGGED_IN && shouldApplyNow() && managesOrb(orb)
				? 1f - Math.max(0, Math.min(100, config.clickThroughTransparency())) / 100f : 1f;
	}

	private boolean managesOrb(String orb)
	{
		switch (orb)
		{
			case "health": return config.manageHealthOrb();
			case "prayer": return config.managePrayerOrb();
			case "run": return config.manageRunOrb();
			case "special": return config.manageSpecialAttackOrb();
			case "worldMap": return config.manageWorldMapOrb();
			case "xp": return config.manageXpOrb();
			case "activity": return config.manageActivityOrb();
			case "wiki": return config.manageWikiOrb();
			case "store": return config.manageStoreOrb();
			case "compass": return config.manageCompassOrb();
			case "logout": return config.manageLogoutOrb();
			default: return false;
		}
	}

	@Subscribe
	public void onPostMenuSort(PostMenuSort event)
	{
		if (!shouldApplyNow())
		{
			return;
		}

		MenuEntry[] entries = client.getMenu().getMenuEntries();

		MenuEntry[] filteredEntries = Arrays.stream(entries)
				.filter(entry -> !isBlockedOrbMenuEntry(entry))
				.toArray(MenuEntry[]::new);

		if (filteredEntries.length != entries.length)
		{
			client.getMenu().setMenuEntries(filteredEntries);
		}
	}

	private void syncState()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		// MAP_NOCLICK bounds are plugin-lifetime changes.
		// They are not tied to hotkey state or individual orb config options.
		syncNoClickRegions();

		boolean shouldApply = shouldApplyNow();

		if (shouldApply)
		{
			applyConfiguredOrbChanges();
			orbWidgetsApplied = true;
		}
		else if (orbWidgetsApplied)
		{
			widgetTransformer.restoreOrbWidgetsChangedByUs();
			orbWidgetsApplied = false;
		}
	}

	private void syncExtraNoClickRegionState()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		int activeMapNoClick0 = getActiveMapNoClick0WidgetId();

		if (activeMapNoClick0 == MODERN_MAP_NOCLICK_0)
		{
			widgetTransformer.patchExtraNoClickRegion(MODERN_MAP_NOCLICK_0);
			widgetTransformer.restoreExtraNoClickRegion(CLASSIC_MAP_NOCLICK_0);
		}
		else if (activeMapNoClick0 == CLASSIC_MAP_NOCLICK_0)
		{
			widgetTransformer.patchExtraNoClickRegion(CLASSIC_MAP_NOCLICK_0);
			widgetTransformer.restoreExtraNoClickRegion(MODERN_MAP_NOCLICK_0);
		}
		else
		{
			widgetTransformer.restoreExtraNoClickRegion(MODERN_MAP_NOCLICK_0);
			widgetTransformer.restoreExtraNoClickRegion(CLASSIC_MAP_NOCLICK_0);
		}
	}

	private boolean shouldApplyNow()
	{
		switch (config.activationMode())
		{
			case HOLD_TO_CLICK_THROUGH:
				return hotkeyHeld;
			case HOLD_TO_RESTORE_CLICKS:
				return !hotkeyHeld;
			case TOGGLE_CLICK_THROUGH:
				return toggleActive;
			default:
				return false;
		}
	}

	private void applyConfiguredOrbChanges()
	{
		if (config.manageWorldMapOrb() && config.suppressOrbTooltips())
		{
			widgetTransformer.hideWidget(WORLDMAP_TOOLTIP);
		}

		if (config.manageHealthOrb())
		{
			widgetTransformer.allowClickThroughTree(HEALTH_CONTAINER);
			widgetTransformer.allowClickThrough(HEALTH_BACKING);
		}

		if (config.managePrayerOrb())
		{
			widgetTransformer.allowClickThroughTree(PRAYER_CONTAINER);
			widgetTransformer.allowClickThrough(PRAYER_BACKING);
		}

		if (config.manageRunOrb())
		{
			widgetTransformer.allowClickThroughTree(RUN_CONTAINER);
			widgetTransformer.allowClickThrough(RUNENERGY_BACKING);
		}

		if (config.manageSpecialAttackOrb())
		{
			widgetTransformer.allowClickThroughTree(SPEC_CONTAINER);
			widgetTransformer.allowClickThrough(SPECENERGY_BACKING);
		}

		if (config.manageWorldMapOrb())
		{
			widgetTransformer.allowClickThroughTree(WORLDMAP_BACKING);
			widgetTransformer.allowClickThrough(WORLDMAP);
		}

		if (config.manageXpOrb())
		{
			widgetTransformer.allowClickThroughTree(XP_DROPS);
		}

		if (config.manageActivityOrb())
		{
			widgetTransformer.allowClickThroughTree(ACTIVITY_BACKING);
			widgetTransformer.allowClickThrough(ACTIVITY_BUTTON);
			widgetTransformer.allowClickThrough(InterfaceID.Orbs.CR_INDICATOR);
			widgetTransformer.allowClickThrough(InterfaceID.Orbs.CR_ICON);
		}

		if (config.manageWikiOrb())
		{
			widgetTransformer.allowClickThroughTree(WIKI_ICON);

			Widget wikiContainer = client.getWidget(WIKI_CONTAINER);

			if (wikiContainer != null)
			{
				widgetTransformer.allowClickThroughTree(WIKI_CONTAINER);

				// The Wiki plugin adds its replacement orb as a dynamic child of WIKI_CONTAINER.
				Widget[] dynamicChildren = wikiContainer.getDynamicChildren();

				if (dynamicChildren != null)
				{
					for (Widget child : dynamicChildren)
					{
						if (child == null)
						{
							continue;
						}

						widgetTransformer.allowClickThrough(child);
					}
				}
			}
		}

		if (config.manageStoreOrb())
		{
			widgetTransformer.allowClickThroughTree(STORE_CONTAINER);
			widgetTransformer.allowClickThrough(STORE_BACKING);
		}

		if (config.manageCompassOrb())
		{
			Widget compassClick = getActiveCompassClickWidget();
			widgetTransformer.allowClickThroughTree(compassClick);
			// Native post-compositing fades this complete area once, including the frame.
			widgetTransformer.excludeTransparencyTree(compassClick);
		}

		if (config.manageLogoutOrb())
		{
			widgetTransformer.allowClickThroughTree(LOGOUT_STONE);
			widgetTransformer.allowClickThroughTree(LOGOUT_ICON);
		}
	}

	private void syncNoClickRegions()
	{
		int activeMapNoClick0 = getActiveMapNoClick0WidgetId();

		if (noClickRegionsSynced && noClickRegionsSyncedForMapNoClick0 == activeMapNoClick0)
		{
			return;
		}

		restoreAllNoClickRegions();
		noClickRegionsSyncedForMapNoClick0 = activeMapNoClick0;

		if (activeMapNoClick0 == NO_ACTIVE_MAP_NOCLICK_0)
		{
			noClickRegionsSynced = true;
			return;
		}

		if (activeMapNoClick0 == MODERN_MAP_NOCLICK_0)
		{
			widgetTransformer.updateNoClickRegions(
					MODERN_MAP_NOCLICK_1,
					MODERN_MAP_NOCLICK_2,
					MODERN_MAP_NOCLICK_3,
					MODERN_MAP_NOCLICK_4,
					MODERN_MAP_NOCLICK_5
			);
		}
		else
		{
			widgetTransformer.updateNoClickRegions(
					CLASSIC_MAP_NOCLICK_1,
					CLASSIC_MAP_NOCLICK_2,
					CLASSIC_MAP_NOCLICK_3,
					CLASSIC_MAP_NOCLICK_4,
					CLASSIC_MAP_NOCLICK_5
			);
		}

		widgetTransformer.patchExtraNoClickRegion(activeMapNoClick0);

		noClickRegionsSynced = true;
	}

	private void restoreAllNoClickRegions()
	{
		widgetTransformer.restoreNoClickRegions(
				MODERN_MAP_NOCLICK_0,
				MODERN_MAP_NOCLICK_1,
				MODERN_MAP_NOCLICK_2,
				MODERN_MAP_NOCLICK_3,
				MODERN_MAP_NOCLICK_4,
				MODERN_MAP_NOCLICK_5,
				CLASSIC_MAP_NOCLICK_0,
				CLASSIC_MAP_NOCLICK_1,
				CLASSIC_MAP_NOCLICK_2,
				CLASSIC_MAP_NOCLICK_3,
				CLASSIC_MAP_NOCLICK_4,
				CLASSIC_MAP_NOCLICK_5
		);
	}

	private int getActiveMapNoClick0WidgetId()
	{
		return selectActiveMapNoClick0(
				client.isResized(),
				isWidgetVisible(MODERN_MAP_NOCLICK_1),
				isWidgetVisible(CLASSIC_MAP_NOCLICK_1),
				client.getWidget(MODERN_MAP_NOCLICK_1) != null,
				client.getWidget(CLASSIC_MAP_NOCLICK_1) != null
		);
	}

	static int selectActiveMapNoClick0(
			boolean resized,
			boolean modernVisible,
			boolean classicVisible,
			boolean modernExists,
			boolean classicExists)
	{
		if (!resized)
		{
			return NO_ACTIVE_MAP_NOCLICK_0;
		}

		if (modernVisible)
		{
			return MODERN_MAP_NOCLICK_0;
		}

		if (classicVisible)
		{
			return CLASSIC_MAP_NOCLICK_0;
		}

		if (modernExists)
		{
			return MODERN_MAP_NOCLICK_0;
		}

		return classicExists ? CLASSIC_MAP_NOCLICK_0 : NO_ACTIVE_MAP_NOCLICK_0;
	}

	private Widget getActiveCompassClickWidget()
	{
		if (!client.isResized())
		{
			return client.getWidget(FIXED_COMPASS_CLICK);
		}
		int activeMapNoClick0 = getActiveMapNoClick0WidgetId();

		if (activeMapNoClick0 == MODERN_MAP_NOCLICK_0)
		{
			return client.getWidget(MODERN_COMPASS_CLICK);
		}

		if (activeMapNoClick0 == CLASSIC_MAP_NOCLICK_0)
		{
			return client.getWidget(CLASSIC_COMPASS_CLICK);
		}

		Widget modernCompassClick = client.getWidget(MODERN_COMPASS_CLICK);
		return modernCompassClick != null ? modernCompassClick : client.getWidget(CLASSIC_COMPASS_CLICK);
	}

	private boolean isWidgetVisible(int widgetId)
	{
		Widget widget = client.getWidget(widgetId);
		return widget != null && !isHiddenOrAncestorHidden(widget);
	}

	private boolean isHiddenOrAncestorHidden(Widget widget)
	{
		Widget current = widget;

		while (current != null)
		{
			if (current.isHidden())
			{
				return true;
			}

			current = current.getParent();
		}

		return false;
	}

	private void markNoClickRegionsDirty()
	{
		noClickRegionsSynced = false;
		noClickRegionsSyncedForMapNoClick0 = NO_ACTIVE_MAP_NOCLICK_0;
	}

	private boolean isBlockedOrbMenuEntry(MenuEntry entry)
	{
		String option = cleanMenuText(entry.getOption());
		String target = cleanMenuText(entry.getTarget());
		int widgetId = entry.getParam1();

		if (config.manageHealthOrb()
				&& isWidgetOrChildOfAny(widgetId, HEALTH_CONTAINER, HEALTH_BUTTON, HEALTH_BACKING)
				&& HEALTH_MENU_OPTIONS.contains(option))
		{
			return true;
		}

		if (config.managePrayerOrb()
				&& isWidgetOrChildOfAny(widgetId, PRAYER_CONTAINER, PRAYER_BUTTON, PRAYER_BACKING)
				&& (PRAYER_MENU_OPTIONS.contains(option) || PRAYER_MENU_TARGETS.contains(target)))
		{
			return true;
		}

		if (config.manageRunOrb()
				&& isWidgetOrChildOfAny(widgetId, RUN_CONTAINER, RUN_BUTTON, RUNENERGY_BACKING)
				&& RUN_MENU_OPTIONS.contains(option))
		{
			return true;
		}

		if (config.manageSpecialAttackOrb()
				&& isWidgetOrChildOfAny(widgetId, SPEC_CONTAINER, SPEC_BUTTON, SPECENERGY_BACKING)
				&& (SPECIAL_ATTACK_MENU_OPTIONS.contains(option) || SPECIAL_ATTACK_MENU_TARGETS.contains(target)))
		{
			return true;
		}

		if (config.manageWorldMapOrb()
				&& isWidgetOrChildOfAny(widgetId, WORLDMAP, WORLDMAP_BACKING)
				&& WORLD_MAP_MENU_OPTIONS.contains(option))
		{
			return true;
		}

		if (config.manageXpOrb()
				&& isWidgetOrChildOfAny(widgetId, XP_DROPS)
				&& (XP_MENU_OPTIONS.contains(option) || XP_MENU_TARGETS.contains(target)))
		{
			return true;
		}

		if (config.manageActivityOrb()
				&& isWidgetOrChildOfAny(widgetId, ACTIVITY_BUTTON, ACTIVITY_BACKING)
				&& ACTIVITY_MENU_OPTIONS.contains(option))
		{
			return true;
		}

		if (config.manageWikiOrb()
				&& isWidgetOrChildOfAny(widgetId, WIKI_ICON, WIKI_CONTAINER)
				&& (WIKI_MENU_OPTIONS.contains(option) || WIKI_MENU_TARGETS.contains(target)))
		{
			return true;
		}

		if (config.manageStoreOrb()
				&& isWidgetOrChildOfAny(widgetId, STORE_CONTAINER, STORE_BUTTON, STORE_BACKING)
				&& STORE_MENU_OPTIONS.contains(option))
		{
			return true;
		}

		if (config.manageCompassOrb()
				&& isWidgetOrChildOfAny(widgetId, MODERN_COMPASS_CLICK, CLASSIC_COMPASS_CLICK, FIXED_COMPASS_CLICK)
				&& COMPASS_MENU_OPTIONS.contains(option))
		{
			return true;
		}

		return config.manageLogoutOrb()
				&& isWidgetOrChildOfAny(widgetId, LOGOUT_STONE, LOGOUT_ICON)
				&& LOGOUT_MENU_OPTIONS.contains(option);
	}

	private boolean isWidgetOrChildOfAny(int widgetId, int... expectedWidgetIds)
	{
		Widget widget = client.getWidget(widgetId);

		while (widget != null)
		{
			for (int expectedWidgetId : expectedWidgetIds)
			{
				if (widget.getId() == expectedWidgetId)
				{
					return true;
				}
			}

			widget = widget.getParent();
		}

		return false;
	}

	private String cleanMenuText(String text)
	{
		if (text == null)
		{
			return "";
		}

		return Text.removeTags(text).trim().toLowerCase(Locale.ROOT);
	}

	@Provides
	OrbClickthroughConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(OrbClickthroughConfig.class);
	}
}

package com.orbclickthrough;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/** Adapters for inspected, unmodified orb overlays. Uses public overlay registration APIs only. */
@Singleton
class OrbOverlayCompatibility
{
    private final OverlayManager overlays;
    private final TooltipManager tooltips;
    private final OrbClickthroughPlugin plugin;
    private final OrbOverlayRenderer renderer;
    private final Map<Overlay, Adapter> adapters = new IdentityHashMap<>();

    @Inject
    OrbOverlayCompatibility(OverlayManager overlays, TooltipManager tooltips, OrbClickthroughPlugin plugin, OrbOverlayRenderer renderer)
    {
        this.overlays = overlays;
        this.tooltips = tooltips;
        this.plugin = plugin;
        this.renderer = renderer;
    }

    void sync()
    {
        List<Overlay> registered = new ArrayList<>();
        // The public predicate API also lets us inspect registrations without reflection.
        overlays.anyMatch(overlay -> { registered.add(overlay); return false; });
        Iterator<Map.Entry<Overlay, Adapter>> iterator = adapters.entrySet().iterator();
        while (iterator.hasNext())
        {
            Map.Entry<Overlay, Adapter> entry = iterator.next();
            if (!registered.contains(entry.getKey()) || !registered.contains(entry.getValue())
                || entry.getKey().getLayer() != OverlayLayer.MANUAL
                || !entry.getKey().getDrawHooks().isEmpty()
                || entry.getKey().getPosition() != entry.getValue().getPosition()
                || entry.getKey().getPriority() != entry.getValue().getPriority())
            {
                restore(entry.getValue());
                iterator.remove();
            }
        }
        for (Overlay overlay : registered)
        {
            String orb = orbFor(overlay.getClass().getName());
            if (overlay instanceof Adapter || orb == null || adapters.containsKey(overlay) || !overlay.getDrawHooks().isEmpty()
                || (overlay.getPosition() != OverlayPosition.DYNAMIC && overlay.getPosition() != OverlayPosition.TOOLTIP && overlay.getPosition() != OverlayPosition.DETACHED)
                || overlay.getLayer() == OverlayLayer.MANUAL)
            {
                continue;
            }
            Adapter adapter = new Adapter(overlay, orb,
                overlay.getClass().getName().equals("io.hydrox.quickprayerpreview.QuickPrayerPreviewOverlay"));
            // Keep the original registered so its owner's remove() still works on plugin shutdown.
            // With no manual draw hooks it stops rendering; adding our adapter rebuilds the layers.
            overlay.setLayer(OverlayLayer.MANUAL);
            adapters.put(overlay, adapter);
            overlays.add(adapter);
        }
    }

    static String orbFor(String className)
    {
        switch (className)
        {
            case "net.runelite.client.plugins.prayer.PrayerDoseOverlay":
            case "net.runelite.client.plugins.prayer.PrayerFlickOverlay":
            case "io.hydrox.quickprayerpreview.QuickPrayerPreviewOverlay": return "prayer";
            case "net.runelite.client.plugins.runenergy.RunEnergyOverlay": return "run";
            case "net.runelite.client.plugins.poison.PoisonOverlay":
            case "com.github.corhen.poisonring.PoisonRingOverlay": return "health";
            case "com.soulreaperaxeqol.SoulreaperAxeQoLNativeOrbOverlay":
            case "com.bram91.specregen.SpecRegenTimerOverlay":
            case "com.soulreaperaxeqol.SoulreaperAxeQoLExtraOrbOverlay": return "special";
            case "net.runelite.client.plugins.regenmeter.RegenMeterOverlay": return "regeneration";
            default: return null;
        }
    }

    void stop()
    {
        for (Adapter adapter : adapters.values())
        {
            restore(adapter);
        }
        adapters.clear();
        renderer.clear();
    }

    private void restore(Adapter adapter)
    {
        if (adapter.original.getLayer() == OverlayLayer.MANUAL)
        {
            adapter.original.setLayer(adapter.originalLayer);
        }
        // Never re-add an original removed by its owner. Removal rebuilds layer registrations.
        overlays.remove(adapter);
    }

    final class Adapter extends Overlay
    {
        private final Overlay original;
        private final OverlayLayer originalLayer;
        private final String orb;
        private final boolean directTooltip;

        Adapter(Overlay original, String orb, boolean directTooltip)
        {
            this.original = original;
            this.originalLayer = original.getLayer();
            this.orb = orb;
            this.directTooltip = directTooltip;
            setPosition(original.getPosition());
            setLayer(originalLayer);
            setPriority(original.getPriority());
        }

        @Override
        public String getName()
        {
            return original.getName();
        }

        @Override
        public Dimension render(Graphics2D graphics)
        {
            // Owner may have stopped after sync(), before this rendering pass.
            if (original.getLayer() != OverlayLayer.MANUAL || !overlays.anyMatch(o -> o == original))
            {
                return null;
            }
            boolean suppress = plugin.suppressPluginTooltip(orb);
            if (suppress && directTooltip)
            {
                original.getBounds().setSize(0, 0);
                return null;
            }
            original.getBounds().setLocation(getBounds().getLocation());
            Set<Tooltip> existing = Collections.newSetFromMap(new IdentityHashMap<>());
            if (suppress)
            {
                existing.addAll(tooltips.getTooltips());
            }
            try
            {
                Dimension size = renderer.render(original, graphics, orb,
                    directTooltip ? 1f : plugin.pluginOverlayOpacity(orb),
                    plugin.pluginOverlayOpacity("health"), plugin.pluginOverlayOpacity("special"));
                original.getBounds().setSize(size == null ? new Dimension() : size);
                return size;
            }
            finally
            {
                if (suppress)
                {
                    // Rendering is synchronous on the client thread. Remove only objects this
                    // known producer just added, preserving every pre-existing tooltip by identity.
                    tooltips.getTooltips().removeIf(tooltip -> !existing.contains(tooltip));
                }
            }
        }
    }
}

package com.orbclickthrough;

import java.awt.AlphaComposite;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.geom.AffineTransform;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;

/** Composites each supported orb drawing once, so overlapping fills don't undo its transparency. */
@Singleton
class OrbOverlayRenderer
{
    private final Client client;
    private BufferedImage buffer;
    private Rectangle dirty;

    @Inject
    OrbOverlayRenderer(Client client)
    {
        this.client = client;
    }

    Dimension render(Overlay overlay, Graphics2D graphics, String orb, float opacity, float health, float special)
    {
        if ("regeneration".equals(orb))
        {
            Graphics2D rings = new RegenGraphics2D((Graphics2D) graphics.create(), health, special);
            try
            {
                return overlay.render(rings);
            }
            finally
            {
                rings.dispose();
            }
        }
        if (opacity == 1f)
        {
            return overlay.render(graphics);
        }
        // An overlay can draw beyond its reported bounds or return null after drawing.
        // Capture the canvas rather than guessing another plugin's offsets or text layout.
        AffineTransform transform = graphics.getTransform();
        Rectangle device = new Rectangle(0, 0, client.getCanvasWidth(), client.getCanvasHeight());
        if (device.isEmpty())
        {
            // Execute tooltip producers on a disposable surface: some supported overlays
            // replace their clip, so an empty clip on the live canvas would not suffice.
            Graphics2D clipped = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
            try
            {
                clipped.clipRect(0, 0, 0, 0);
                return overlay.render(clipped);
            }
            finally
            {
                clipped.dispose();
            }
        }
        if (buffer == null || buffer.getWidth() != device.width || buffer.getHeight() != device.height)
        {
            buffer = new BufferedImage(device.width, device.height, BufferedImage.TYPE_INT_ARGB);
            dirty = null;
        }
        Graphics2D offscreen = buffer.createGraphics();
        DrawingBoundsGraphics2D.Drawing drawing = new DrawingBoundsGraphics2D.Drawing(device);
        Dimension size;
        try
        {
            offscreen.setComposite(AlphaComposite.Clear);
            if (dirty != null) offscreen.fillRect(dirty.x, dirty.y, dirty.width, dirty.height);
            offscreen.setComposite(AlphaComposite.SrcOver);
            offscreen.setRenderingHints(graphics.getRenderingHints());
            offscreen.setFont(graphics.getFont());
            offscreen.setPaint(graphics.getPaint());
            offscreen.setStroke(graphics.getStroke());
            offscreen.setBackground(graphics.getBackground());
            offscreen.translate(-device.x, -device.y);
            offscreen.transform(transform);
            offscreen.setClip(graphics.getClip());
            size = overlay.render(new DrawingBoundsGraphics2D(offscreen, drawing));
        }
        finally
        {
            offscreen.dispose();
            dirty = drawing.bounds;
            if (dirty != null) composite(graphics, dirty, opacity);
        }
        return size;
    }

    private void composite(Graphics2D graphics, Rectangle device, float opacity)
    {
        if (opacity == 0f) return;
        Graphics2D output = (Graphics2D) graphics.create();
        try
        {
            AlphaComposite composite = graphics.getComposite() instanceof AlphaComposite
                ? (AlphaComposite) graphics.getComposite() : AlphaComposite.SrcOver;
            output.setComposite(composite.derive(composite.getAlpha() * opacity));
            output.setTransform(new AffineTransform());
            output.drawImage(buffer, device.x, device.y, device.x + device.width, device.y + device.height,
                device.x, device.y, device.x + device.width, device.y + device.height, null);
        }
        finally
        {
            output.dispose();
        }
    }

    void clear()
    {
        buffer = null;
        dirty = null;
    }

}

package com.orbclickthrough;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;

@Singleton
public class OrbWidgetTransformer
{
    // Small always-on trims so noclick regions do not overlap exposed orb edges.
    private static final int MAP_NOCLICK_1_SHRINK_LEFT = 4;
    private static final int MAP_NOCLICK_2_SHRINK_LEFT = 4;
    private static final int MAP_NOCLICK_4_SHRINK_LEFT = 6;

    private static final int MAP_NOCLICK_3_SHRINK_RIGHT = 20;
    private static final int MAP_NOCLICK_4_SHRINK_RIGHT = 33;
    private static final int MAP_NOCLICK_5_SHRINK_RIGHT = 40;

    private static final int MAP_NOCLICK_0_SHRINK_WIDTH = 37;
    private static final int MAP_NOCLICK_0_MOVE_LEFT = 11;
    private static final int MAP_NOCLICK_0_SHIFT_DOWN = 24;
    private static final int MAP_NOCLICK_0_HEIGHT = 24;

    // Extra dynamic blocker created by this plugin.
    // Needed because shrinking MAP_NOCLICK_0 exposes part of the minimap between the logout/radar widget areas.
    private static final int MAP_NOCLICK_EXTRA_MOVE_LEFT = 18;
    private static final int MAP_NOCLICK_EXTRA_MOVE_UP = 22;
    private static final int MAP_NOCLICK_EXTRA_EXTRA_WIDTH = -34;
    private static final int MAP_NOCLICK_EXTRA_HEIGHT = 23;

    private final Client client;

    private final Set<Integer> extraNoClickRegionPatched = new HashSet<>();
    private final Map<Integer, Widget> extraNoClickRegions = new HashMap<>();

    private final Set<Widget> hiddenByUs = Collections.newSetFromMap(new IdentityHashMap<>());
    private final Set<Widget> noClickThroughChangedByUs = Collections.newSetFromMap(new IdentityHashMap<>());
    private final Set<Widget> transparencyExcluded = Collections.newSetFromMap(new IdentityHashMap<>());
    private final Set<Widget> targetVerbChangedByUs = Collections.newSetFromMap(new IdentityHashMap<>());
    private final Set<Widget> actionsChangedByUs = Collections.newSetFromMap(new IdentityHashMap<>());
    private final Set<Integer> boundsChangedByUs = new HashSet<>();

    private final Map<Widget, Boolean> originalNoClickThrough = new IdentityHashMap<>();
    private final Map<Widget, String> originalTargetVerb = new IdentityHashMap<>();
    private final Map<Widget, String[]> originalActions = new IdentityHashMap<>();
    private final Map<Widget, Integer> originalOpacity = new IdentityHashMap<>();
    private final Map<Widget, Boolean> transparencyVisibility = new IdentityHashMap<>();
    private final Map<Widget, Integer> hoverSprites = new IdentityHashMap<>();
    private final Map<Widget, Boolean> hoverTooltipVisibility = new IdentityHashMap<>();
    private final Map<Integer, WidgetBounds> originalBounds = new HashMap<>();

    @Inject
    public OrbWidgetTransformer(Client client)
    {
        this.client = client;
    }

    public void hideWidget(int widgetId)
    {
        hideWidget(client.getWidget(widgetId));
    }

    public void hideWidget(Widget widget)
    {
        if (widget == null || widget.isHidden())
        {
            return;
        }

        widget.setHidden(true);
        hiddenByUs.add(widget);
    }

    public void allowClickThrough(int widgetId)
    {
        allowClickThrough(client.getWidget(widgetId));
    }

    /**
     * Makes a widget and every current descendant click-through.
     *
     * Targeting the whole orb subtree makes this resilient to Jagex inserting a
     * new visual or blocking layer beneath an existing, stable orb container.
     * Calling this repeatedly is safe: allowClickThrough(Widget) records the
     * original value only once for each widget instance.
     */
    public void allowClickThroughTree(int widgetId)
    {
        allowClickThroughTree(client.getWidget(widgetId));
    }

    public void allowClickThroughTree(Widget widget)
    {
        allowClickThroughTree(widget, Collections.newSetFromMap(new IdentityHashMap<>()));
    }

    public void excludeTransparencyTree(Widget root)
    {
        if (root == null || !transparencyExcluded.add(root)) return;
        for (Widget[] children : new Widget[][]{root.getStaticChildren(), root.getDynamicChildren(), root.getNestedChildren()})
            if (children != null)
                for (Widget child : children) excludeTransparencyTree(child);
    }

    private void allowClickThroughTree(Widget root, Set<Widget> visited)
    {
        if (root == null || !visited.add(root))
        {
            return;
        }

        allowClickThrough(root);

        allowClickThroughChildren(root.getStaticChildren(), visited);
        allowClickThroughChildren(root.getDynamicChildren(), visited);
        allowClickThroughChildren(root.getNestedChildren(), visited);
    }

    private void allowClickThroughChildren(Widget[] descendants, Set<Widget> visited)
    {
        if (descendants == null)
        {
            return;
        }

        for (Widget descendant : descendants)
        {
            allowClickThroughTree(descendant, visited);
        }
    }

    public void applyTransparency(int percent)
    {
        transparencyVisibility.forEach(Widget::setHidden);
        transparencyVisibility.clear();
        int clampedPercent = Math.max(0, Math.min(100, percent));
        if (clampedPercent == 0)
        {
            restoreTransparency();
            return;
        }

        for (Widget widget : noClickThroughChangedByUs)
        {
            // Layers do not draw; apply alpha to their individual visual children.
            if (widget.getType() == WidgetType.LAYER || transparencyExcluded.contains(widget))
            {
                continue;
            }
            int original = originalOpacity.computeIfAbsent(widget, Widget::getOpacity);
            widget.setOpacity(original + Math.round((255 - original) * clampedPercent / 100f));
            // Native sprite alpha is 256 - opacity: opacity 255 still draws at 1/256.
            // Hide visual widgets for an exact 100%, and restore before scripts run again.
            if (clampedPercent == 100)
            {
                transparencyVisibility.computeIfAbsent(widget, Widget::isSelfHidden);
                widget.setHidden(true);
            }
        }
    }

    public void restoreTransparency()
    {
        originalOpacity.forEach(Widget::setOpacity);
        originalOpacity.clear();
        transparencyVisibility.forEach(Widget::setHidden);
        transparencyVisibility.clear();
    }

    public boolean isMouseOverManagedOrb()
    {
        Point mouse = client.getMouseCanvasPosition();
        if (mouse == null)
        {
            return false;
        }
        for (Widget widget : noClickThroughChangedByUs)
        {
            if (!widget.isHidden() && widget.contains(mouse))
            {
                return true;
            }
        }
        return false;
    }

    public void suppressHoverEffects()
    {
        // Only normalize hover sprites for drawing. Disabling widget listeners
        // would also stop stat/var/timer updates, freezing the live orb contents.
        for (Widget widget : noClickThroughChangedByUs)
        {
            int sprite = widget.getSpriteId();
            int normal = normalOrbSprite(sprite);
            if (normal != sprite)
            {
                hoverSprites.putIfAbsent(widget, sprite);
                widget.setSpriteId(normal);
            }
        }
        if (isMouseOverManagedOrb())
        {
            hideHoverTooltip(client.getWidget(InterfaceID.Orbs.TOOLTIP));
            hideHoverTooltip(client.getWidget(InterfaceID.Orbs.WORLDMAP_TOOLTIP));
        }
    }

    private void hideHoverTooltip(Widget widget)
    {
        if (widget != null)
        {
            hoverTooltipVisibility.putIfAbsent(widget, widget.isSelfHidden());
            widget.setHidden(true);
        }
    }

    public void restoreHoverEffects()
    {
        hoverSprites.forEach(Widget::setSpriteId);
        hoverSprites.clear();
        hoverTooltipVisibility.forEach(Widget::setHidden);
        hoverTooltipVisibility.clear();
    }

    static int normalOrbSprite(int sprite)
    {
        switch (sprite)
        {
            case SpriteID.OrbFrame.FRAME_HOVERED: return SpriteID.OrbFrame.FRAME;
            case SpriteID.OrbXp.HOVERED: return SpriteID.OrbXp.ORB;
            case SpriteID.OrbXp.ACTIVATED_HOVERED: return SpriteID.OrbXp.ACTIVATED;
            case SpriteID.WorldmapIcon._1: return SpriteID.WorldmapIcon._0;
            case SpriteID.WorldmapIcon._3: return SpriteID.WorldmapIcon._2;
            case SpriteID.WorldmapIcon._5: return SpriteID.WorldmapIcon._4;
            case SpriteID.WorldmapIcon._7: return SpriteID.WorldmapIcon._6;
            case SpriteID.WorldmapIconLarge._1: return SpriteID.WorldmapIconLarge._0;
            case SpriteID.WorldmapIconLarge._3: return SpriteID.WorldmapIconLarge._2;
            case SpriteID.WorldmapIconLarge._5: return SpriteID.WorldmapIconLarge._4;
            case SpriteID.WorldmapIconLarge._7: return SpriteID.WorldmapIconLarge._6;
            case SpriteID.WikiIcon.SELECTED: return SpriteID.WikiIcon.DESELECTED;
            case SpriteID.Ring34._1: return SpriteID.Ring34._0;
            default: return sprite;
        }
    }

