package com.github.corhen.poisonring;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.geom.Arc2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.ComponentID;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class PoisonRingOverlay extends Overlay {
    private final Client client;
    private final PoisonRingPlugin plugin;
    private final PoisonRingConfig config;

    @Inject
    public PoisonRingOverlay(Client client, PoisonRingPlugin plugin, PoisonRingConfig config) {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DETACHED);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!plugin.isPoisoned()) {
            return null;
        }

        Widget healthOrb = client.getWidget(ComponentID.MINIMAP_HEALTH_ORB);
        if (healthOrb == null || healthOrb.isHidden()) {
            return null;
        }

        Rectangle bounds = healthOrb.getBounds();

        int baseOrbX = bounds.x + (bounds.width - bounds.height);
        int baseOrbY = bounds.y;

        int finalX = baseOrbX + config.shiftX();
        int finalY = baseOrbY + config.shiftY();
        int finalDiameter = bounds.height + config.diameter();

        double progress;
        if (config.testMode() && plugin.getTicksUntilDamage() == 0) {
            progress = 0.5; // Show a half-circle in test mode so you can see the arc
        } else {
            progress = (double) plugin.getTicksUntilDamage() / plugin.getPoisonTickRate();
        }

        int startAngle = 90;
        int extent = (int) -(360 * progress);

        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        graphics.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
        graphics.setColor(plugin.isVenom() ? config.venomColor() : config.poisonColor());
        graphics.setStroke(new BasicStroke(config.lineThickness()));

        Arc2D.Double arc = new Arc2D.Double(
            finalX,
            finalY,
            finalDiameter,
            finalDiameter,
            startAngle,
            extent,
            Arc2D.OPEN
        );

        graphics.draw(arc);

        return null;
    }
}

package com.github.corhen.poisonring;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.HitsplatID;
import net.runelite.api.VarPlayer;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
    name = "Poison Ring",
    description = "Adds a ring around the HP orb showing time until next poison/venom tick",
    tags = {"poison", "venom", "hp", "orb", "timer", "combat"}
)
public class PoisonRingPlugin extends Plugin {
    @Inject
    private Client client;

    @Inject
    private PoisonRingConfig config;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private PoisonRingOverlay overlay;

    private int poisonValue = 0;
    private int ticksUntilDamage = 0;
    private boolean isVenom = false;

    private static final int POISON_TICK_RATE = 30;

    @Provides
    PoisonRingConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(PoisonRingConfig.class);
    }

    @Override
    protected void startUp() {
        overlayManager.add(overlay);
        checkPoisonState();
    }

    @Override
    protected void shutDown() {
        overlayManager.remove(overlay);
        poisonValue = 0;
        ticksUntilDamage = 0;
        isVenom = false;
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event) {
        if (event.getVarpId() == VarPlayer.POISON) {
            checkPoisonState();
        }
    }

    private void checkPoisonState() {
        int newValue = client.getVarpValue(VarPlayer.POISON);

        if (newValue <= 0) {
            poisonValue = 0;
            ticksUntilDamage = 0;
            isVenom = false;
        } else {
            if (poisonValue <= 0 || (newValue >= 1000000 && poisonValue < 1000000)) {
                ticksUntilDamage = POISON_TICK_RATE;
            }
            poisonValue = newValue;
            isVenom = newValue >= 1000000;
        }
    }

    @Subscribe
    public void onHitsplatApplied(HitsplatApplied event) {
        if (event.getActor() == client.getLocalPlayer()) {
            int hitsplatType = event.getHitsplat().getHitsplatType();
            if (hitsplatType == HitsplatID.POISON || hitsplatType == HitsplatID.VENOM) {
                ticksUntilDamage = POISON_TICK_RATE;
            }
        }
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        if (poisonValue > 0 && ticksUntilDamage > 0) {
            ticksUntilDamage--;
        }
    }

    public int getTicksUntilDamage() { return ticksUntilDamage; }
    public boolean isPoisoned() {
        return poisonValue > 0 || config.testMode();
    }
    public boolean isVenom() { return isVenom; }
    public int getPoisonTickRate() { return POISON_TICK_RATE; }
}

package com.orbclickthrough;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.BufferProvider;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayManager;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CompassAppearanceTest
{
    @Test
    public void fadesActualNeedleAndFramePixelsInEveryLayoutWithoutChangingSurroundings()
    {
        for (boolean gpu : new boolean[]{false, true})
            for (int id : new int[]{InterfaceID.ToplevelPreEoc.MAP_MINIMAP_GRAPHIC6,
                InterfaceID.ToplevelOsrsStretch.MAP_MINIMAP_GRAPHIC6, InterfaceID.Toplevel.MAPCONTAINER_GRAPHIC3})
            {
                Client client = mock(Client.class);
                OrbClickthroughPlugin plugin = mock(OrbClickthroughPlugin.class);
                OverlayManager manager = mock(OverlayManager.class);
                List<Overlay> overlays = new ArrayList<>();
                when(manager.add(any())).thenAnswer(call -> overlays.add(call.getArgument(0)));
                BufferProvider buffer = mock(BufferProvider.class);
                int[] pixels = new int[100 * 100];
                when(buffer.getPixels()).thenReturn(pixels);
                when(buffer.getWidth()).thenReturn(100);
                when(buffer.getHeight()).thenReturn(100);
                when(client.getBufferProvider()).thenReturn(buffer);
                when(client.isGpu()).thenReturn(gpu);
                boolean resized = id != InterfaceID.Toplevel.MAPCONTAINER_GRAPHIC3;
                when(client.isResized()).thenReturn(resized);
                Widget compass = mock(Widget.class);
                when(compass.getBounds()).thenReturn(new Rectangle(30, 30, 35, 35));
                when(compass.getContentType()).thenReturn(1339);
                when(client.getWidget(id)).thenReturn(compass);
                CompassAppearance appearance = new CompassAppearance(client, plugin, manager);
                for (float opacity : new float[]{.5f, 0f, 1f})
                {
                    when(plugin.nativeOrbOpacity("compass")).thenReturn(opacity);
                    Arrays.fill(pixels, 0xff224466);
                    appearance.beginFrame();
                    overlays.get(0).render(null); // scene before widgets
                    for (int y = 26; y < 69; y++)
                        for (int x = 26; x < 69; x++) pixels[y * 100 + x] = 0xffcc8844;
                    overlays.get(1).render(null); // game-drawn compass and shared frame
                    int expectedBackground = resized ? 0xff224466 : (gpu ? 0 : 0xff000000);
                    assertEquals(CompassAppearance.blend(0xffcc8844, expectedBackground, opacity), pixels[47 * 100 + 47]);
                    assertEquals(0xffcc8844, pixels[26 * 100 + 26]); // outside circular compass
                    // Outline/shadow beyond the old needle-mask + two-pixel crop.
                    assertEquals(CompassAppearance.blend(0xffcc8844, expectedBackground, opacity), pixels[47 * 100 + 27]);
                    assertEquals(0xff224466, pixels[80 * 100 + 80]); // minimap/world outside compass
                    overlays.get(1).render(null);
                    assertEquals(CompassAppearance.blend(0xffcc8844, expectedBackground, opacity), pixels[47 * 100 + 47]);
                    if (!resized && opacity != 1f)
                    {
                        // The next frame can reuse the native compass without repainting it.
                        appearance.beginFrame();
                        assertEquals(0xffcc8844, pixels[47 * 100 + 47]);
                        overlays.get(1).render(null);
                        assertEquals(CompassAppearance.blend(0xffcc8844, expectedBackground, opacity), pixels[47 * 100 + 47]);
                        // A subsequent drawing (e.g. a menu) must survive restoration.
                        pixels[47 * 100 + 47] = 0xffabcdef;
                    }
                    appearance.stop();
                    assertEquals(!resized && opacity != 1f ? 0xffabcdef : 0xffcc8844, pixels[47 * 100 + 47]);
                    // restart installs fresh hooks
                    overlays.clear();
                }
            }
    }

    @Test
    public void premultipliedGpuFadeChangesColourAndAlphaTogether()
    {
        assertEquals(0x80604020, CompassAppearance.blend(0xffc08040, 0, .5f));
        assertEquals(0, CompassAppearance.blend(0xffc08040, 0, 0f));
        assertEquals(0xffc08040, CompassAppearance.blend(0xffc08040, 0, 1f));
    }
}

package com.orbclickthrough;

import java.lang.reflect.Field;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.api.Client;
import net.runelite.api.GameState;
